const store = $getWorkflowStaticData('global');
const res = $input.first().json;
const series = res.results && res.results[0] && res.results[0].series ? res.results[0].series[0] : null;
if (!store.last) { store.last = Date.now(); return []; }   // first run: remember "now", send nothing old
if (!series) return [];
const fmt = (signal, v) => {
  v = Number(v);
  if (signal === 'cpu') return `${(v * 100).toFixed(1)}% of one CPU core`;
  if (signal === 'memory') return `${v.toFixed(0)} MB`;
  return `${v.toFixed(0)} ms`;
};
const out = [];
let newest = store.last;
for (const row of series.values) {
  const r = {};
  series.columns.forEach((c, i) => { r[c] = row[i]; });
  if (r.time > store.last) {
    const minutes = Math.max(1, Math.round(Number(r.minutes_to_threshold)));
    out.push({ json: { text:
      `Early warning: ${r.signal} is rising steadily\n` +
      `Now ${fmt(r.signal, r.current)}, heading for ${fmt(r.signal, r.level)} in about ${minutes} min at this pace\n\n` +
      `This is a warning only. No restart or rollback is started unless the detector flags the service.` } });
    if (r.time > newest) newest = r.time;
  }
}
store.last = newest;
return out;
